insert into public.recipe_versions (id, recipe_id, version, servings, prep_minutes, cook_minutes) values ('00000000-0000-4000-8000-0e0000000001', '00000000-0000-4000-8000-0ec100000001', 1, 2, 10, 24) on conflict (id) do nothing;
insert into public.recipe_translations (recipe_id, locale, title, description, accessories, safety_notes, source_note) values ('00000000-0000-4000-8000-0ec100000001', 'en', 'Lemon & herb chicken thighs', 'Bone-in thighs with crackling skin and a bright lemon, garlic and thyme rub. A weeknight staple that needs almost no attention.', '["Instant-read thermometer"]'::jsonb, '["Poultry is safe to eat once the thickest part reaches 74 °C (165 °F). Use a thermometer rather than colour.","Wash hands, boards and utensils after handling raw chicken."]'::jsonb, 'Original CookPilot demonstration recipe. Not yet physically tested on a specific model — check doneness yourself and adjust times to your appliance.') on conflict (recipe_id, locale) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000001', 'en', 1, 'Bone-in, skin-on chicken thighs', 4, 'piece', 'about 600 g', false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000001', 'en', 2, 'Olive oil', 1, 'tbsp', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000001', 'en', 3, 'Lemon', 1, 'piece', 'zest and juice', false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000001', 'en', 4, 'Garlic cloves, finely grated', 2, 'clove', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000001', 'en', 5, 'Fresh thyme leaves', 2, 'tsp', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000001', 'en', 6, 'Fine sea salt', 1, 'tsp', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000001', 'en', 7, 'Black pepper', null, null, 'to taste', false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000001', 'en', 1, 'Pat the chicken thighs very dry with kitchen paper. Mix the oil, lemon zest, garlic, thyme, salt and pepper, then rub it all over the chicken, including under the skin.', null, null, null, null, 'Dry skin is what makes it crisp.') on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000001', 'en', 2, 'Preheat the air fryer on Air Fry at 200 °C for 3 minutes.', 'air-fry', null, 200, 180, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000001', 'en', 3, 'Place the thighs skin-side down in a single layer. Cook for 12 minutes.', 'air-fry', null, 200, 720, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000001', 'en', 4, 'Turn the thighs skin-side up and cook for 10–12 minutes more, until the skin is deep golden and the thickest part reaches 74 °C.', 'air-fry', null, 200, 660, 'Measure next to the bone without touching it.') on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000001', 'en', 5, 'Rest for 5 minutes, squeeze over the lemon juice and serve.', null, null, null, 300, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_translations (recipe_id, locale, title, description, accessories, safety_notes, source_note) values ('00000000-0000-4000-8000-0ec100000001', 'fr', 'Hauts de cuisse de poulet citron et herbes', 'Des hauts de cuisse à la peau croustillante, frottés au citron, à l''ail et au thym. Un classique de semaine qui demande très peu d''attention.', '["Thermomètre à lecture instantanée"]'::jsonb, '["La volaille est sûre lorsque la partie la plus épaisse atteint 74 °C (165 °F). Fiez-vous à un thermomètre plutôt qu''à la couleur.","Lavez-vous les mains, ainsi que les planches et ustensiles, après avoir manipulé du poulet cru."]'::jsonb, 'Recette de démonstration originale CookPilot. Pas encore testée physiquement sur un modèle précis — vérifiez la cuisson et ajustez les temps à votre appareil.') on conflict (recipe_id, locale) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000001', 'fr', 1, 'Hauts de cuisse de poulet avec os et peau', 4, 'piece', 'environ 600 g', false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000001', 'fr', 2, 'Huile d''olive', 1, 'tbsp', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000001', 'fr', 3, 'Citron', 1, 'piece', 'zeste et jus', false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000001', 'fr', 4, 'Gousses d''ail finement râpées', 2, 'clove', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000001', 'fr', 5, 'Feuilles de thym frais', 2, 'tsp', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000001', 'fr', 6, 'Sel fin', 1, 'tsp', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000001', 'fr', 7, 'Poivre noir', null, null, 'selon le goût', false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000001', 'fr', 1, 'Séchez soigneusement les hauts de cuisse avec du papier absorbant. Mélangez l''huile, le zeste de citron, l''ail, le thym, le sel et le poivre, puis frottez-en le poulet, y compris sous la peau.', null, null, null, null, 'Une peau bien sèche est le secret du croustillant.') on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000001', 'fr', 2, 'Préchauffez l''air fryer en mode Air Fry à 200 °C pendant 3 minutes.', 'air-fry', null, 200, 180, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000001', 'fr', 3, 'Déposez les hauts de cuisse côté peau vers le bas, en une seule couche. Faites cuire 12 minutes.', 'air-fry', null, 200, 720, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000001', 'fr', 4, 'Retournez les hauts de cuisse, peau vers le haut, et poursuivez la cuisson 10 à 12 minutes, jusqu''à ce que la peau soit bien dorée et que la partie la plus épaisse atteigne 74 °C.', 'air-fry', null, 200, 660, 'Mesurez près de l''os, sans le toucher.') on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000001', 'fr', 5, 'Laissez reposer 5 minutes, arrosez de jus de citron et servez.', null, null, null, 300, null) on conflict (version_id, locale, position) do nothing;
