insert into public.recipe_translations (recipe_id, locale, title, description, accessories, safety_notes, source_note) values ('00000000-0000-4000-8000-0ec100000002', 'en', 'Crispy paprika potato wedges', 'Soaked, dried and lightly oiled wedges that come out crisp at the edges and fluffy inside.', '[]'::jsonb, '["The basket and drawer are very hot after cooking — use the handle and place the drawer on a heat-proof surface."]'::jsonb, 'Original CookPilot demonstration recipe. Not yet physically tested on a specific model — check doneness yourself and adjust times to your appliance.') on conflict (recipe_id, locale) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000002', 'en', 1, 'Floury potatoes', 500, 'g', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000002', 'en', 2, 'Neutral oil', 1, 'tbsp', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000002', 'en', 3, 'Smoked paprika', 1, 'tsp', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000002', 'en', 4, 'Garlic powder', 0.5, 'tsp', null, true) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000002', 'en', 5, 'Fine sea salt', 0.5, 'tsp', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000002', 'en', 1, 'Cut the potatoes into even wedges, about 2 cm thick. Soak in cold water for 10 minutes, then drain and dry thoroughly in a clean towel.', null, null, null, 600, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000002', 'en', 2, 'Toss the wedges with the oil, paprika, garlic powder and salt until evenly coated.', null, null, null, null, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000002', 'en', 3, 'Cook on Air Fry at 200 °C for 10 minutes in a single, loose layer.', 'air-fry', null, 200, 600, 'Crowding the basket steams the potatoes — cook in two batches if needed.') on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000002', 'en', 4, 'Shake the basket well, then cook for 10–12 minutes more until golden and crisp.', 'air-fry', null, 200, 660, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_translations (recipe_id, locale, title, description, accessories, safety_notes, source_note) values ('00000000-0000-4000-8000-0ec100000002', 'fr', 'Potatoes croustillantes au paprika', 'Des quartiers de pommes de terre trempés, séchés et légèrement huilés : croustillants sur les bords, moelleux à cœur.', '[]'::jsonb, '["Le panier et le tiroir sont très chauds après la cuisson — utilisez la poignée et posez le tiroir sur une surface résistante à la chaleur."]'::jsonb, 'Recette de démonstration originale CookPilot. Pas encore testée physiquement sur un modèle précis — vérifiez la cuisson et ajustez les temps à votre appareil.') on conflict (recipe_id, locale) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000002', 'fr', 1, 'Pommes de terre à chair farineuse', 500, 'g', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000002', 'fr', 2, 'Huile neutre', 1, 'tbsp', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000002', 'fr', 3, 'Paprika fumé', 1, 'tsp', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000002', 'fr', 4, 'Ail en poudre', 0.5, 'tsp', null, true) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000002', 'fr', 5, 'Sel fin', 0.5, 'tsp', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000002', 'fr', 1, 'Coupez les pommes de terre en quartiers réguliers d''environ 2 cm d''épaisseur. Faites-les tremper 10 minutes dans l''eau froide, puis égouttez et séchez-les soigneusement dans un torchon propre.', null, null, null, 600, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000002', 'fr', 2, 'Mélangez les quartiers avec l''huile, le paprika, l''ail en poudre et le sel jusqu''à ce qu''ils soient bien enrobés.', null, null, null, null, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000002', 'fr', 3, 'Faites cuire en mode Air Fry à 200 °C pendant 10 minutes, en une seule couche aérée.', 'air-fry', null, 200, 600, 'Un panier trop rempli fait cuire les pommes de terre à la vapeur — procédez en deux fois si besoin.') on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000002', 'fr', 4, 'Secouez bien le panier, puis poursuivez la cuisson 10 à 12 minutes jusqu''à ce qu''elles soient dorées et croustillantes.', 'air-fry', null, 200, 660, null) on conflict (version_id, locale, position) do nothing;
