insert into public.recipe_translations (recipe_id, locale, title, description, accessories, safety_notes, source_note) values ('00000000-0000-4000-8000-0ec100000003', 'en', 'Honey & thyme roasted carrots', 'Tender, lightly caramelised carrots finished with honey and thyme. Simple enough for a Tuesday, pretty enough for guests.', '[]'::jsonb, '["Honey is not suitable for children under one year old."]'::jsonb, 'Original CookPilot demonstration recipe. Not yet physically tested on a specific model — check doneness yourself and adjust times to your appliance.') on conflict (recipe_id, locale) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000003', 'en', 1, 'Carrots', 400, 'g', 'halved lengthways if thick', false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000003', 'en', 2, 'Olive oil', 1, 'tbsp', null, false) on conflict (version_id, locale, position) do nothing;
