insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000003', 'en', 1, 'Toss the carrots with the olive oil and salt.', null, null, null, null, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000003', 'en', 2, 'Cook on Roast at 190 °C for 12 minutes, shaking the basket halfway through.', 'roast', null, 190, 720, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000003', 'en', 3, 'Drizzle over the honey, add the thyme and toss. Cook for 3–4 minutes more, until glossy and tender when pierced with a knife.', 'roast', null, 190, 210, 'Honey burns quickly — add it only at the end.') on conflict (version_id, locale, position) do nothing;
insert into public.recipe_translations (recipe_id, locale, title, description, accessories, safety_notes, source_note) values ('00000000-0000-4000-8000-0ec100000003', 'fr', 'Carottes rôties au miel et au thym', 'Des carottes tendres et légèrement caramélisées, relevées de miel et de thym. Assez simples pour un mardi soir, assez jolies pour recevoir.', '[]'::jsonb, '["Le miel ne convient pas aux enfants de moins d''un an."]'::jsonb, 'Recette de démonstration originale CookPilot. Pas encore testée physiquement sur un modèle précis — vérifiez la cuisson et ajustez les temps à votre appareil.') on conflict (recipe_id, locale) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000003', 'fr', 1, 'Carottes', 400, 'g', 'coupées en deux dans la longueur si elles sont épaisses', false) on conflict (version_id, locale, position) do nothing;
