insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000003', 'fr', 4, 'Brins de thym frais', 3, 'sprig', null, false) on conflict (version_id, locale, position) do nothing;
