insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000003', 'fr', 1, 'Mélangez les carottes avec l''huile d''olive et le sel.', null, null, null, null, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000003', 'fr', 2, 'Faites cuire en mode Roast à 190 °C pendant 12 minutes, en secouant le panier à mi-cuisson.', 'roast', null, 190, 720, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000003', 'fr', 3, 'Arrosez de miel, ajoutez le thym et mélangez. Poursuivez la cuisson 3 à 4 minutes, jusqu''à ce que les carottes soient brillantes et tendres sous la pointe d''un couteau.', 'roast', null, 190, 210, 'Le miel brûle vite — ajoutez-le seulement en fin de cuisson.') on conflict (version_id, locale, position) do nothing;
