insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000004', 'en', 1, 'Pat the salmon dry, rub with half the oil and season with salt.', null, null, null, null, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000004', 'en', 2, 'Cook skin-side down on Air Fry at 200 °C for 8–10 minutes, depending on thickness, until the flesh flakes easily and the centre reaches 63 °C.', 'air-fry', null, 200, 540, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000004', 'en', 3, 'Stir together the lemon juice, dill and remaining oil. Spoon over the salmon and serve straight away.', null, null, null, null, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_translations (recipe_id, locale, title, description, accessories, safety_notes, source_note) values ('00000000-0000-4000-8000-0ec100000004', 'fr', 'Pavés de saumon au citron et à l''aneth', 'Un saumon cuit juste à point, doré en surface, avec une sauce minute au citron et à l''aneth. À table en un quart d''heure.', '["Thermomètre à lecture instantanée"]'::jsonb, '["Les agences de sécurité alimentaire recommandent de cuire le poisson à une température à cœur de 63 °C (145 °F).","Contient du poisson."]'::jsonb, 'Recette de démonstration originale CookPilot. Pas encore testée physiquement sur un modèle précis — vérifiez la cuisson et ajustez les temps à votre appareil.') on conflict (recipe_id, locale) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000004', 'fr', 1, 'Pavés de saumon avec la peau', 2, 'piece', 'environ 150 g chacun', false) on conflict (version_id, locale, position) do nothing;
