insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000004', 'fr', 4, 'Jus de citron', 1, 'tbsp', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000004', 'fr', 5, 'Aneth frais ciselé', 1, 'tbsp', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000004', 'fr', 1, 'Séchez le saumon, frottez-le avec la moitié de l''huile et salez.', null, null, null, null, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000004', 'fr', 2, 'Faites cuire côté peau vers le bas en mode Air Fry à 200 °C pendant 8 à 10 minutes selon l''épaisseur, jusqu''à ce que la chair s''effeuille facilement et que le cœur atteigne 63 °C.', 'air-fry', null, 200, 540, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000004', 'fr', 3, 'Mélangez le jus de citron, l''aneth et le reste d''huile. Nappez le saumon et servez aussitôt.', null, null, null, null, null) on conflict (version_id, locale, position) do nothing;
