insert into public.recipe_translations (recipe_id, locale, title, description, accessories, safety_notes, source_note) values ('00000000-0000-4000-8000-0ec100000005', 'en', 'Grilled ribeye with garlic butter', 'A thick ribeye seared on a hot grill plate and finished with garlic-parsley butter. Cook to temperature, not to time.', '["Grill plate","Instant-read thermometer"]'::jsonb, '["Food-safety agencies recommend 63 °C (145 °F) plus a 3-minute rest for whole cuts of beef. Medium-rare is below that; it is a personal choice and not advised for pregnant, elderly or immunocompromised people.","Grilling fatty cuts produces smoke — keep the appliance clear of cupboards and ventilate the kitchen.","Contains milk (butter)."]'::jsonb, 'Original CookPilot demonstration recipe. Not yet physically tested on a specific model — check doneness yourself and adjust times to your appliance.') on conflict (recipe_id, locale) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000005', 'en', 1, 'Ribeye steak, 3 cm thick', 500, 'g', 'at room temperature for 30 minutes', false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000005', 'en', 2, 'Neutral oil with a high smoke point', 2, 'tsp', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000005', 'en', 3, 'Flaky sea salt', 1, 'tsp', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000005', 'en', 4, 'Butter, softened', 30, 'g', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000005', 'en', 5, 'Garlic clove, finely grated', 1, 'clove', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000005', 'en', 6, 'Chopped flat-leaf parsley', 1, 'tbsp', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000005', 'en', 1, 'Mash the butter with the garlic and parsley and set aside. Pat the steak dry, rub with oil and season generously with salt.', null, null, null, null, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000005', 'en', 2, 'Fit the grill plate, close the lid and preheat on Grill, HIGH, until the appliance signals it is ready.', 'grill', 'HIGH', null, null, 'A fully preheated plate gives proper grill marks.') on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000005', 'en', 3, 'Lay the steak on the plate, close the lid and grill for 4 minutes.', 'grill', 'HIGH', null, 240, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000005', 'en', 4, 'Flip and grill for 3–5 minutes more. Start checking early: remove at 52–54 °C for medium-rare (it will rise a few degrees while resting), or 63 °C for the officially recommended doneness.', 'grill', 'HIGH', null, 240, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000005', 'en', 5, 'Top with the garlic butter and rest for 5 minutes before slicing against the grain.', null, null, null, 300, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_translations (recipe_id, locale, title, description, accessories, safety_notes, source_note) values ('00000000-0000-4000-8000-0ec100000005', 'fr', 'Entrecôte grillée au beurre d''ail', 'Une entrecôte épaisse saisie sur une plaque bien chaude et terminée au beurre d''ail et persil. Cuisez à la température, pas à la minute.', '["Plaque de gril","Thermomètre à lecture instantanée"]'::jsonb, '["Les agences de sécurité alimentaire recommandent 63 °C (145 °F) suivis de 3 minutes de repos pour les pièces de bœuf entières. Une cuisson saignante se situe en dessous : c''est un choix personnel, déconseillé aux femmes enceintes, aux personnes âgées ou immunodéprimées.","La cuisson de pièces grasses dégage de la fumée — éloignez l''appareil des placards et aérez la cuisine.","Contient du lait (beurre)."]'::jsonb, 'Recette de démonstration originale CookPilot. Pas encore testée physiquement sur un modèle précis — vérifiez la cuisson et ajustez les temps à votre appareil.') on conflict (recipe_id, locale) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000005', 'fr', 1, 'Entrecôte de 3 cm d''épaisseur', 500, 'g', 'sortie 30 minutes à l''avance', false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000005', 'fr', 2, 'Huile neutre à point de fumée élevé', 2, 'tsp', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000005', 'fr', 3, 'Fleur de sel', 1, 'tsp', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000005', 'fr', 4, 'Beurre mou', 30, 'g', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000005', 'fr', 5, 'Gousse d''ail finement râpée', 1, 'clove', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000005', 'fr', 6, 'Persil plat ciselé', 1, 'tbsp', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000005', 'fr', 1, 'Écrasez le beurre avec l''ail et le persil, puis réservez. Séchez l''entrecôte, huilez-la et salez généreusement.', null, null, null, null, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000005', 'fr', 2, 'Installez la plaque de gril, fermez le couvercle et préchauffez en mode Grill, niveau HIGH, jusqu''à ce que l''appareil signale qu''il est prêt.', 'grill', 'HIGH', null, null, 'Une plaque bien préchauffée assure un beau marquage.') on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000005', 'fr', 3, 'Posez l''entrecôte sur la plaque, fermez le couvercle et faites griller 4 minutes.', 'grill', 'HIGH', null, 240, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000005', 'fr', 4, 'Retournez et faites griller encore 3 à 5 minutes. Contrôlez tôt : retirez à 52–54 °C pour une cuisson saignante à rosée (la température monte encore de quelques degrés au repos), ou à 63 °C pour la cuisson officiellement recommandée.', 'grill', 'HIGH', null, 240, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000005', 'fr', 5, 'Déposez le beurre d''ail sur la viande et laissez reposer 5 minutes avant de trancher perpendiculairement aux fibres.', null, null, null, 300, null) on conflict (version_id, locale, position) do nothing;
