insert into public.recipe_translations (recipe_id, locale, title, description, accessories, safety_notes, source_note) values ('00000000-0000-4000-8000-0ec100000006', 'en', 'Grilled vegetable skewers with herb oil', 'Courgette, pepper, red onion and mushrooms, lightly charred and brushed with a lemony herb oil.', '["Grill plate","Short skewers that fit under the closed lid"]'::jsonb, '["Skewer tips and the grill plate stay hot — use tongs to turn and serve."]'::jsonb, 'Original CookPilot demonstration recipe. Not yet physically tested on a specific model — check doneness yourself and adjust times to your appliance.') on conflict (recipe_id, locale) do nothing;
