insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000006', 'en', 8, 'Fine sea salt', 0.5, 'tsp', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000006', 'en', 1, 'If you use wooden skewers, soak them in water for 15 minutes. Thread the vegetables, alternating colours, and brush with half the olive oil. Season with salt.', null, null, null, null, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000006', 'en', 2, 'Fit the grill plate, close the lid and preheat on Grill, MED.', 'grill', 'MED', null, null, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000006', 'en', 3, 'Grill the skewers for 8–10 minutes, turning them halfway, until tender with charred edges.', 'grill', 'MED', null, 540, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000006', 'en', 4, 'Mix the remaining oil with the lemon juice and herbs, and brush over the hot skewers.', null, null, null, null, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_translations (recipe_id, locale, title, description, accessories, safety_notes, source_note) values ('00000000-0000-4000-8000-0ec100000006', 'fr', 'Brochettes de légumes grillés à l''huile d''herbes', 'Courgette, poivron, oignon rouge et champignons, légèrement grillés et badigeonnés d''une huile d''herbes citronnée.', '["Plaque de gril","Piques courtes tenant sous le couvercle fermé"]'::jsonb, '["Les pointes des piques et la plaque restent brûlantes — utilisez une pince pour retourner et servir."]'::jsonb, 'Recette de démonstration originale CookPilot. Pas encore testée physiquement sur un modèle précis — vérifiez la cuisson et ajustez les temps à votre appareil.') on conflict (recipe_id, locale) do nothing;
