insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000006', 'fr', 1, 'Si vous utilisez des piques en bois, faites-les tremper 15 minutes dans l''eau. Enfilez les légumes en alternant les couleurs, puis badigeonnez-les de la moitié de l''huile d''olive. Salez.', null, null, null, null, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000006', 'fr', 2, 'Installez la plaque de gril, fermez le couvercle et préchauffez en mode Grill, niveau MED.', 'grill', 'MED', null, null, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000006', 'fr', 3, 'Faites griller les brochettes 8 à 10 minutes en les retournant à mi-cuisson, jusqu''à ce que les légumes soient tendres et marqués.', 'grill', 'MED', null, 540, null) on conflict (version_id, locale, position) do nothing;
