insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000007', 'en', 4, 'Double (heavy) cream', 180, 'ml', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000007', 'en', 5, 'Whole milk', 240, 'ml', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000007', 'en', 1, 'Whisk the cream cheese, sugar and vanilla seeds into a smooth paste. Gradually whisk in the cream and milk until the sugar has dissolved.', null, null, null, null, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000007', 'en', 2, 'Pour into the pint without going over the max fill line. Close the lid and freeze on a level surface for 24 hours.', null, null, null, 86400, 'A level, fully frozen base is essential for the blade to process it evenly.') on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000007', 'en', 3, 'Remove the lid, lock the pint into the outer bowl and the machine, and run the Ice Cream program.', 'ice-cream', null, null, null, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000007', 'en', 4, 'If the texture is crumbly, add a tablespoon of milk and process once more. Serve straight away.', null, null, null, null, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_translations (recipe_id, locale, title, description, accessories, safety_notes, source_note) values ('00000000-0000-4000-8000-0ec100000007', 'fr', 'Glace à la vanille en gousse', 'Une base sans cuisson au fromage frais qui donne une glace vanille lisse et onctueuse. Préparez la base aujourd''hui, turbinez demain.', '["Un pot CREAMi (16 oz / 473 ml) avec couvercle"]'::jsonb, '["Contient du lait.","Ne turbinez jamais un pot congelé de travers ou rempli au-delà du repère maximal."]'::jsonb, 'Recette de démonstration originale CookPilot. Pas encore testée physiquement sur un modèle précis — vérifiez la cuisson et ajustez les temps à votre appareil.') on conflict (recipe_id, locale) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000007', 'fr', 1, 'Fromage frais entier, ramolli', 15, 'g', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000007', 'fr', 2, 'Sucre en poudre', 65, 'g', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000007', 'fr', 3, 'Gousse de vanille, graines grattées', 1, 'piece', 'ou 1 c. à café d''extrait de vanille', false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000007', 'fr', 4, 'Crème liquide entière', 180, 'ml', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000007', 'fr', 5, 'Lait entier', 240, 'ml', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000007', 'fr', 1, 'Fouettez le fromage frais, le sucre et les graines de vanille jusqu''à obtenir une pâte lisse. Incorporez peu à peu la crème et le lait jusqu''à dissolution du sucre.', null, null, null, null, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000007', 'fr', 2, 'Versez dans le pot sans dépasser le repère de remplissage maximal. Fermez le couvercle et congelez à plat pendant 24 heures.', null, null, null, 86400, 'Une base bien plane et entièrement congelée est indispensable pour un turbinage homogène.') on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000007', 'fr', 3, 'Retirez le couvercle, verrouillez le pot dans le bol extérieur puis sur la machine, et lancez le programme Ice Cream.', 'ice-cream', null, null, null, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000007', 'fr', 4, 'Si la texture est friable, ajoutez une cuillère à soupe de lait et turbinez une seconde fois. Servez aussitôt.', null, null, null, null, null) on conflict (version_id, locale, position) do nothing;
