insert into public.recipe_translations (recipe_id, locale, title, description, accessories, safety_notes, source_note) values ('00000000-0000-4000-8000-0ec100000008', 'en', 'Mango & lime sorbet', 'Three ingredients, intensely fruity and naturally dairy-free. The lime keeps the mango bright.', '["One CREAMi pint (16 oz / 473 ml) with lid"]'::jsonb, '["Never process a pint that was frozen at an angle or filled above the max line."]'::jsonb, 'Original CookPilot demonstration recipe. Not yet physically tested on a specific model — check doneness yourself and adjust times to your appliance.') on conflict (recipe_id, locale) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000008', 'en', 1, 'Ripe mango flesh', 400, 'g', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000008', 'en', 2, 'Caster sugar', 40, 'g', 'adjust to the sweetness of the fruit', false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000008', 'en', 3, 'Lime juice', 2, 'tbsp', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000008', 'en', 1, 'Blend the mango, sugar and lime juice to a completely smooth purée.', null, null, null, null, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000008', 'en', 2, 'Pour into the pint up to the max fill line, tap to remove air pockets, close and freeze on a level surface for 24 hours.', null, null, null, 86400, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000008', 'en', 3, 'Remove the lid, lock the pint into the machine and run the Sorbet program.', 'sorbet', null, null, null, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000008', 'en', 4, 'If it looks powdery, add a tablespoon of water or juice and process again until smooth.', null, null, null, null, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_translations (recipe_id, locale, title, description, accessories, safety_notes, source_note) values ('00000000-0000-4000-8000-0ec100000008', 'fr', 'Sorbet mangue et citron vert', 'Trois ingrédients, un goût de fruit intense et naturellement sans lactose. Le citron vert réveille la mangue.', '["Un pot CREAMi (16 oz / 473 ml) avec couvercle"]'::jsonb, '["Ne turbinez jamais un pot congelé de travers ou rempli au-delà du repère maximal."]'::jsonb, 'Recette de démonstration originale CookPilot. Pas encore testée physiquement sur un modèle précis — vérifiez la cuisson et ajustez les temps à votre appareil.') on conflict (recipe_id, locale) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000008', 'fr', 1, 'Chair de mangue bien mûre', 400, 'g', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000008', 'fr', 2, 'Sucre en poudre', 40, 'g', 'à ajuster selon le fruit', false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_ingredients (version_id, locale, position, name, quantity, unit, note, optional) values ('00000000-0000-4000-8000-0e0000000008', 'fr', 3, 'Jus de citron vert', 2, 'tbsp', null, false) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000008', 'fr', 1, 'Mixez la mangue, le sucre et le jus de citron vert jusqu''à obtenir une purée parfaitement lisse.', null, null, null, null, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000008', 'fr', 2, 'Versez dans le pot jusqu''au repère maximal, tapotez pour chasser les bulles d''air, fermez et congelez à plat pendant 24 heures.', null, null, null, 86400, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000008', 'fr', 3, 'Retirez le couvercle, verrouillez le pot sur la machine et lancez le programme Sorbet.', 'sorbet', null, null, null, null) on conflict (version_id, locale, position) do nothing;
insert into public.recipe_steps (version_id, locale, position, instruction, program, level, temperature_c, duration_seconds, tip) values ('00000000-0000-4000-8000-0e0000000008', 'fr', 4, 'Si la texture est poudreuse, ajoutez une cuillère à soupe d''eau ou de jus et turbinez à nouveau jusqu''à obtenir un sorbet lisse.', null, null, null, null, null) on conflict (version_id, locale, position) do nothing;
